using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ── Configuration ──────────────────────────────────────────────────────────────
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍  Researching: {topic}\n");

// ── Tools ──────────────────────────────────────────────────────────────────────
var notebook = new Notebook();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(
        ([Description("The search query")] string query) => WebSearchTool.SearchAsync(query),
        "web_search",
        "Searches the web for information. Returns a list of results with titles, snippets, and URLs."),

    AIFunctionFactory.Create(
        ([Description("A concise note to save")] string note) => notebook.AddNote(note),
        "take_note",
        "Saves an important finding to the notebook for later use in the summary."),

    AIFunctionFactory.Create(
        () => notebook.GetNotes(),
        "read_notes",
        "Reads all notes taken so far."),
};

// ── Chat client with automatic tool invocation ─────────────────────────────────
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

var systemPrompt = $"""
    You are a research agent. Your goal is to thoroughly research the following topic
    and produce a well-structured summary.

    **Topic:** {topic}

    Follow this process:
    1. Search the web for relevant information (make 2-4 searches with varied queries).
    2. Take notes on the most important findings from each search.
    3. Read your notes to review what you have gathered.
    4. Produce a final Markdown summary with sections, key facts, and source URLs.

    Be thorough but concise. Cite sources where possible.
    """;

var messages = new List<ChatMessage>
{
    new(ChatRole.System, systemPrompt),
    new(ChatRole.User, $"Please research this topic: {topic}"),
};

// ── Agent loop ─────────────────────────────────────────────────────────────────
// UseFunctionInvocation handles tool calls automatically; we just stream the
// final assistant response.

Console.ForegroundColor = ConsoleColor.DarkGray;
Console.WriteLine("Agent is working (tool calls are handled automatically)…\n");
Console.ResetColor();

notebook.OnNoteAdded += note =>
{
    Console.ForegroundColor = ConsoleColor.DarkYellow;
    Console.WriteLine($"  📝 Note saved: {Truncate(note, 90)}");
    Console.ResetColor();
};

WebSearchTool.OnSearch += query =>
{
    Console.ForegroundColor = ConsoleColor.DarkCyan;
    Console.WriteLine($"  🌐 Searching: {query}");
    Console.ResetColor();
};

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine();
Console.ForegroundColor = ConsoleColor.Green;
Console.WriteLine("═══════════════════  Research Summary  ═══════════════════");
Console.ResetColor();
Console.WriteLine(response.Text);
Console.WriteLine();

return;

// ── Helpers ────────────────────────────────────────────────────────────────────
static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing"
        : input;
}

static string Truncate(string text, int maxLength) =>
    text.Length <= maxLength ? text : text[..(maxLength - 1)] + "…";

// ── Web Search Tool ────────────────────────────────────────────────────────────
static class WebSearchTool
{
    private static readonly HttpClient Http = new();
    public static event Action<string>? OnSearch;

    public static async Task<string> SearchAsync(string query)
    {
        OnSearch?.Invoke(query);

        try
        {
            // Use DuckDuckGo Lite HTML endpoint (no API key required).
            var url = $"https://lite.duckduckgo.com/lite/?q={Uri.EscapeDataString(query)}";
            var request = new HttpRequestMessage(HttpMethod.Get, url);
            request.Headers.UserAgent.ParseAdd(
                "Mozilla/5.0 (compatible; ResearchAgent/1.0)");

            var response = await Http.SendAsync(request);
            response.EnsureSuccessStatusCode();
            var html = await response.Content.ReadAsStringAsync();

            var results = ParseDuckDuckGoLite(html);

            return results.Count == 0
                ? "No results found."
                : JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseDuckDuckGoLite(string html)
    {
        // DDG Lite returns a simple HTML table. Extract result links and snippets.
        var results = new List<SearchResult>();
        var span = html.AsSpan();

        var searchIndex = 0;
        while (results.Count < 8)
        {
            // Find result links: <a rel="nofollow" href="..." class="result-link">
            const string linkMarker = "class=\"result-link\"";
            var linkPos = html.IndexOf(linkMarker, searchIndex, StringComparison.Ordinal);
            if (linkPos < 0) break;

            // Extract href
            var hrefStart = html.LastIndexOf("href=\"", linkPos, linkPos - searchIndex, StringComparison.Ordinal);
            if (hrefStart < 0) { searchIndex = linkPos + linkMarker.Length; continue; }
            hrefStart += 6;
            var hrefEnd = html.IndexOf('"', hrefStart);
            var href = html[hrefStart..hrefEnd];

            // Extract link text (title)
            var titleStart = html.IndexOf('>', linkPos) + 1;
            var titleEnd = html.IndexOf("</a>", titleStart, StringComparison.Ordinal);
            var title = StripHtml(html[titleStart..titleEnd]).Trim();

            // Look for the snippet in the next <td> with class="result-snippet"
            const string snippetMarker = "class=\"result-snippet\"";
            var snippetPos = html.IndexOf(snippetMarker, titleEnd, StringComparison.Ordinal);
            var snippet = "";
            if (snippetPos >= 0 && snippetPos < titleEnd + 2000)
            {
                var sStart = html.IndexOf('>', snippetPos) + 1;
                var sEnd = html.IndexOf("</td>", sStart, StringComparison.Ordinal);
                if (sEnd > sStart)
                    snippet = StripHtml(html[sStart..sEnd]).Trim();
            }

            if (!string.IsNullOrWhiteSpace(title) && href.StartsWith("http"))
                results.Add(new SearchResult(title, snippet, href));

            searchIndex = titleEnd + 1;
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        var result = new System.Text.StringBuilder(html.Length);
        var inTag = false;
        foreach (var ch in html)
        {
            if (ch == '<') { inTag = true; continue; }
            if (ch == '>') { inTag = false; continue; }
            if (!inTag) result.Append(ch);
        }
        return System.Net.WebUtility.HtmlDecode(result.ToString());
    }

    private record SearchResult(string Title, string Snippet, string Url);
}

